#!/usr/bin/env node
// Writes _category_.json files so the autogenerated API sidebar shows modules and
// sub-modules with the right labels and order. Runs after gen-api-docs.
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const manifest = JSON.parse(await readFile(path.join(root, 'spec', 'modules.json'), 'utf8'));

async function write(dir, label, position) {
  await mkdir(dir, { recursive: true });
  const cat = { label, collapsible: true, collapsed: true, ...(position ? { position } : {}) };
  await writeFile(path.join(dir, '_category_.json'), JSON.stringify(cat, null, 2) + '\n');
}

for (const m of manifest) {
  const moduleDir = path.join(root, 'docs', 'api', m.module.dir);
  await write(moduleDir, m.module.label, m.module.position);
  if (m.sub) await write(path.join(root, m.outputDir), m.sub.label, m.sub.position);
}
console.log(`[api-categories] wrote categories for ${manifest.length} module specs`);
